package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.special.Gamma;

/** Threshold-adjusted polychoric DWLS with full-moment sandwich and scaled/shifted test. */
public final class OrdinalSem {
    private OrdinalSem(){}
    public record Options(int maxIterations,double gradientTolerance,double functionTolerance,double confidence,int minimumCategoryCount){public Options{Inference.confidence(confidence);if(maxIterations<1||maxIterations>20000||!(gradientTolerance>0)||!Double.isFinite(gradientTolerance)||!(functionTolerance>0)||!Double.isFinite(functionTolerance)||minimumCategoryCount<1||minimumCategoryCount>100)throw new IllegalArgumentException("Invalid ordinal estimation settings.");}public static Options defaults(){return new Options(1500,1e-8,1e-12,.95,5);}}
    public record Term(String parameter,double estimate,double robustStandardError,double z,double pValue,double lower,double upper){}
    public record Fit(SemModel.Model model,Options options,Polychoric.Fit moments,int iterations,boolean converged,boolean locallyIdentified,boolean boundary,double discrepancy,double unadjustedStatistic,int degreesOfFreedom,double scalingFactor,double shift,double adjustedStatistic,double adjustedPValue,double[] estimates,double[][] parameterCovariance,List<Term> terms,double[][] impliedCorrelation,double[][] residualCorrelation,double[][] fullCovariance,List<String> warnings){public Fit{estimates=estimates.clone();parameterCovariance=Matrices.copy(parameterCovariance);terms=List.copyOf(terms);impliedCorrelation=Matrices.copy(impliedCorrelation);residualCorrelation=Matrices.copy(residualCorrelation);fullCovariance=Matrices.copy(fullCovariance);warnings=List.copyOf(warnings);}@Override public double[] estimates(){return estimates.clone();}@Override public double[][] parameterCovariance(){return Matrices.copy(parameterCovariance);}@Override public double[][] impliedCorrelation(){return Matrices.copy(impliedCorrelation);}@Override public double[][] residualCorrelation(){return Matrices.copy(residualCorrelation);}@Override public double[][] fullCovariance(){return Matrices.copy(fullCovariance);}}
    record Evaluation(double value,double[] gradient,double[][] correlation,double[][] jacobian,CovarianceSem.State state){}
    static final class Work {
        final CovarianceSem.Work ram;final Polychoric.Fit moments;final double[] weights;final int q,p,m;
        Work(SemModel.Model model,Polychoric.Fit moments){this.moments=moments;p=moments.names().size();q=model.parameters().size();m=p*(p-1)/2;weights=new double[m];for(int j=0;j<m;j++){double v=moments.momentCovariance()[j][j];if(!(v>0)||!Double.isFinite(v))throw new IllegalArgumentException("Ordinal moment variance is nonpositive or unresolved.");weights[j]=1/v;}double[][] identity=new double[p][p];for(int j=0;j<p;j++)identity[j][j]=1;ram=new CovarianceSem.Work(identity,new double[p],model,new CovarianceSem.Options(1000,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,false,.95,CovarianceSem.Information.OBSERVED));}
        Evaluation state(double[] theta){var state=ram.state(theta);if(state==null||!CovarianceSem.properDisturbance(state.disturbance().getData(),state.fullCovariance().getData()))return null;RealMatrix v=state.covariance();double[][] correlations=new double[p][p],jacobian=new double[m][q];double[] gradient=new double[q];for(int i=0;i<p;i++)correlations[i][i]=1;double value=0;int k=0;for(int a=0;a<p;a++)for(int b=a+1;b<p;b++){double sdA=Math.sqrt(v.getEntry(a,a)),sdB=Math.sqrt(v.getEntry(b,b)),rho=v.getEntry(a,b)/sdA/sdB,e=rho-moments.correlation()[a][b];correlations[a][b]=correlations[b][a]=rho;value+=weights[k]*e*e;for(int j=0;j<q;j++){var dv=state.covarianceDerivatives().get(j);double derivative=dv.getEntry(a,b)/sdA/sdB-.5*rho*(dv.getEntry(a,a)/v.getEntry(a,a)+dv.getEntry(b,b)/v.getEntry(b,b));jacobian[k][j]=derivative;gradient[j]+=2*weights[k]*e*derivative;}k++;}return new Evaluation(value,gradient,correlations,jacobian,state);}
        Bfgs.Evaluation evaluate(double[] theta){var state=state(theta);return state==null?new Bfgs.Evaluation(Double.POSITIVE_INFINITY,new double[q]):new Bfgs.Evaluation(state.value(),state.gradient());}
    }
    public static Fit fit(int[][] codes,List<String> names,List<List<String>> levels,SemModel.Model model,Options options){
        Objects.requireNonNull(options);int p=names.size(),q=model.parameters().size(),m=p*(p-1)/2;if(p!=model.observed().length||model.variables().size()>64||q>m)throw new IllegalArgumentException("Ordinal model/data dimensions differ, exceed 64 total variables, or have more parameters than response correlations.");Set<Integer> observed=new HashSet<>();int[] order=model.observed();for(int j=0;j<p;j++){observed.add(order[j]);if(!names.get(j).equals(model.variables().get(order[j])))throw new IllegalArgumentException("Ordinal observed-variable identities/order differ from the data.");if(!(model.covariance()[order[j]][order[j]]>0))throw new IllegalArgumentException("Fix each observed-response residual scale to a positive constant (theta parameterization).");}for(double intercept:model.intercepts())if(intercept!=0)throw new IllegalArgumentException("Ordinal response/factor means are fixed to zero; thresholds carry the response locations.");for(var parameter:model.parameters())for(var location:parameter.locations())if(location.kind()==SemModel.Kind.INTERCEPT||location.kind()==SemModel.Kind.COVARIANCE&&location.row()==location.column()&&observed.contains(location.row()))throw new IllegalArgumentException("Ordinal means and observed-response residual scales are fixed; do not free their parameters.");
        var moments=Polychoric.fit(codes,names,levels,options.minimumCategoryCount());var work=new Work(model,moments);double[] start=new double[q],low=new double[q],high=new double[q];for(int j=0;j<q;j++){var par=model.parameters().get(j);start[j]=par.start()/par.scale();low[j]=par.lower()==null?Double.NEGATIVE_INFINITY:par.lower()/par.scale();high[j]=par.upper()==null?Double.POSITIVE_INFINITY:par.upper()/par.scale();}var optimum=Bfgs.minimize(work::evaluate,start,low,high,options.maxIterations(),options.gradientTolerance(),options.functionTolerance());double[] theta=optimum.point();var state=work.state(theta);if(state==null)throw new IllegalArgumentException("Final ordinal model is inadmissible.");boolean boundary=false;for(int j=0;j<q;j++)if(Double.isFinite(low[j])&&theta[j]-low[j]<1e-7||Double.isFinite(high[j])&&high[j]-theta[j]<1e-7)boundary=true;boolean identified=q==0;double[][] covariance=new double[q][q];for(var row:covariance)Arrays.fill(row,Double.NaN);RealMatrix weight=MatrixUtils.createRealDiagonalMatrix(work.weights),projection=weight;RealMatrix gamma=new Array2DRowRealMatrix(moments.momentCovariance());
        if(q>0){RealMatrix jacobian=new Array2DRowRealMatrix(state.jacobian()),breadMatrix=jacobian.transpose().multiply(weight).multiply(jacobian);double[][] normalized=breadMatrix.getData();for(int i=0;i<q;i++)for(int j=0;j<q;j++)normalized[i][j]/=Math.sqrt(breadMatrix.getEntry(i,i)*breadMatrix.getEntry(j,j));identified=Arrays.stream(normalized).flatMapToDouble(Arrays::stream).allMatch(Double::isFinite)&&Matrices.minEigenvalue(normalized)>1e-9;if(identified)try{RealMatrix bread=new CholeskyDecomposition(breadMatrix,1e-8,1e-12).getSolver().getInverse(),map=bread.multiply(jacobian.transpose()).multiply(weight),sandwich=map.multiply(gamma).multiply(map.transpose());projection=weight.subtract(weight.multiply(jacobian).multiply(bread).multiply(jacobian.transpose()).multiply(weight));if(optimum.converged()&&!boundary)for(int i=0;i<q;i++)for(int j=0;j<q;j++)covariance[i][j]=sandwich.getEntry(i,j)*model.parameters().get(i).scale()*model.parameters().get(j).scale()/codes.length;}catch(NonPositiveDefiniteMatrixException|NonSymmetricMatrixException invalid){identified=false;}}
        int df=m-q;double unadjusted=codes.length*state.value(),scale=Double.NaN,shift=Double.NaN,adjusted=Double.NaN,pvalue=Double.NaN;boolean regular=identified&&optimum.converged()&&!boundary;if(regular&&df>0){RealMatrix product=projection.multiply(gamma);double trace=product.getTrace(),trace2=product.multiply(product).getTrace();if(trace2>1e-12&&Double.isFinite(trace2)){scale=Math.sqrt(trace2/df);shift=df-trace/scale;adjusted=unadjusted/scale+shift;pvalue=Gamma.regularizedGammaQ(df*.5,Math.max(0,adjusted)*.5);}}
        List<String> warnings=new ArrayList<>(moments.warnings());warnings.add("Polychoric DWLS uses diagonal weights for estimation and the full threshold-adjusted moment covariance for sandwich SE and a scaled/shifted mean-variance adjusted test. Raw category-code distances are not used as measurements.");warnings.add("Reported parameters use the fixed observed-response residual scales and factor markers. Thresholds are standardized marginal-response cut points; factor/response means are fixed to zero. This is not continuous-data ML/FIML or a claim of native package numerical parity.");if(!identified)warnings.add("The ordinal correlation Jacobian is singular or numerically weak; inference is unavailable.");if(!optimum.converged())warnings.add("Ordinal optimizer convergence was not established; point results are provisional and inference is unavailable.");if(boundary)warnings.add("A parameter is on a configured bound; ordinary sandwich/Wald and adjusted test inference are unavailable.");if(df==0)warnings.add("The specified response-correlation model is just identified; no absolute model-fit test is available.");if(m>=codes.length)warnings.add("The empirical moment covariance has limited finite-sample rank; asymptotic fit-test calibration needs particular caution.");
        double critical=new NormalDistribution().inverseCumulativeProbability((1+options.confidence())/2);double[] estimates=new double[q];List<Term> terms=new ArrayList<>();for(int j=0;j<q;j++){var parameter=model.parameters().get(j);double value=estimates[j]=theta[j]*parameter.scale(),se=Math.sqrt(covariance[j][j]);boolean variance=parameter.locations().stream().anyMatch(l->l.kind()==SemModel.Kind.COVARIANCE);double z=variance?Double.NaN:Inference.ratio(value,se);terms.add(new Term(parameter.name(),value,se,z,Inference.normalTwoSided(z),value-critical*se,value+critical*se));}double[][] residual=new double[p][p];for(int i=0;i<p;i++)for(int j=0;j<p;j++)residual[i][j]=moments.correlation()[i][j]-state.correlation()[i][j];return new Fit(model,options,moments,optimum.iterations(),optimum.converged(),identified,boundary,state.value(),unadjusted,df,scale,shift,adjusted,pvalue,estimates,covariance,terms,state.correlation(),residual,state.state().fullCovariance().getData(),warnings);
    }
    /** Reflective theta-scale builder: fixed unit marker, unit response residuals, free factor disturbances. */
    public static SemModel.Prepared reflective(List<String> names,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges){if(blocks.isEmpty())throw new IllegalArgumentException("Define at least one reflective factor.");LinkedHashSet<Integer> selected=new LinkedHashSet<>();for(var block:blocks){if(block.measurementType()!=PlsSem.MeasurementType.REFLECTIVE||block.columns().length<3)throw new IllegalArgumentException("The ordinal builder requires reflective factors with at least three indicators.");for(int col:block.columns())if(col<0||col>=names.size()||!selected.add(col))throw new IllegalArgumentException("Ordinal factor indicators must be distinct and available.");}int[] columns=selected.stream().mapToInt(Integer::intValue).toArray();int p=columns.length,size=p+blocks.size();double[][] a=new double[size][size],s=new double[size][size];List<String> variables=new ArrayList<>();for(int col:columns)variables.add(names.get(col));for(var block:blocks)variables.add("Factor: "+block.name());List<SemModel.Parameter> parameters=new ArrayList<>();Map<Integer,Integer> position=new HashMap<>();for(int j=0;j<p;j++){position.put(columns[j],j);s[j][j]=1;}int[] factors=new int[blocks.size()];for(int j=0;j<blocks.size();j++){factors[j]=p+j;var block=blocks.get(j);parameters.add(new SemModel.Parameter("Factor disturbance variance: "+block.name(),List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,p+j,p+j)),1,1,1e-6,null));for(int k=0;k<block.columns().length;k++){int indicator=position.get(block.columns()[k]);if(k==0)a[indicator][p+j]=1;else parameters.add(new SemModel.Parameter("Loading: "+block.name()+" -> "+names.get(block.columns()[k]),List.of(new SemModel.Location(SemModel.Kind.DIRECTED,indicator,p+j)),.8,1));}}
        boolean[] endogenous=new boolean[blocks.size()];Set<PlsSem.Edge> unique=new HashSet<>();for(var edge:edges){if(edge.source()<0||edge.target()<0||edge.source()>=blocks.size()||edge.target()>=blocks.size()||edge.source()==edge.target()||!unique.add(edge))throw new IllegalArgumentException("Invalid ordinal structural edge.");endogenous[edge.target()]=true;parameters.add(new SemModel.Parameter("Path: "+blocks.get(edge.source()).name()+" -> "+blocks.get(edge.target()).name(),List.of(new SemModel.Location(SemModel.Kind.DIRECTED,p+edge.target(),p+edge.source())),.1,1));}for(int i=0;i<blocks.size();i++)for(int j=0;j<i;j++)if(!endogenous[i]&&!endogenous[j])parameters.add(new SemModel.Parameter("Exogenous covariance: "+blocks.get(j).name()+" / "+blocks.get(i).name(),List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,p+i,p+j)),0,1));return new SemModel.Prepared(new SemModel.Model(variables,java.util.stream.IntStream.range(0,p).toArray(),a,s,new double[size],parameters),columns,factors);
    }
}
